    private func _parseArticulation(_ track: Track, _ node: XmlNode, _ isInstrumentSet: Bool, _ elementName: String) {
        let articulation: InstrumentArticulation = InstrumentArticulation()
        articulation.outputMidiNumber = -1.0
        articulation.elementType = elementName
        var name: String = ""
        for c in node.childElements() {
            let txt: String = c.innerText
            switch c.localName! {
            case "Name":
                name = c.innerText
            case "InputMidiNumbers":
                articulation.id = GpifParser._parseIntSafe(txt.splitBy(" ")[0], 0.0)
            case "OutputMidiNumber":
                articulation.outputMidiNumber = GpifParser._parseIntSafe(txt, 0.0)
            case "TechniqueSymbol":
                articulation.techniqueSymbol = GpifParser.parseTechniqueSymbol(txt)
            case "TechniquePlacement":
                articulation.techniqueSymbolPlacement = GpifParser.parseTechniqueSymbolPlacement(txt)
            case "Noteheads":
                let noteHeadsTxt: List<String> = GpifParser._splitSafe(txt)
                if noteHeadsTxt.length >= 1 {
                    articulation.noteHeadDefault = GpifParser.parseNoteHead(noteHeadsTxt[0])
                }
                if noteHeadsTxt.length >= 2 {
                    articulation.noteHeadHalf = GpifParser.parseNoteHead(noteHeadsTxt[1])
                }
                if noteHeadsTxt.length >= 3 {
                    articulation.noteHeadWhole = GpifParser.parseNoteHead(noteHeadsTxt[2])
                }
                if articulation.noteHeadHalf == MusicFontSymbol.None {
                    articulation.noteHeadHalf = articulation.noteHeadDefault
                }
                if articulation.noteHeadWhole == MusicFontSymbol.None {
                    articulation.noteHeadWhole = articulation.noteHeadDefault
                }
            case "StaffLine":
                articulation.staffLine = GpifParser._parseIntSafe(txt, 0.0)
            default:
                break
            }
        }
        let fullName: String = "\((elementName).toTemplate()).\((name).toTemplate())"
        if isInstrumentSet {
            track.percussionArticulations.push(articulation)
            self._articulationByName.set(fullName, articulation)
        } else if self._articulationByName.has(fullName) {
            self._articulationByName.get(fullName)!.staffLine = articulation.staffLine
        }
    }

    internal static func parseTechniqueSymbol(_ txt: String) -> MusicFontSymbol {
        switch txt {
        case "pictEdgeOfCymbal":
            return MusicFontSymbol.PictEdgeOfCymbal
        case "articStaccatoAbove":
            return MusicFontSymbol.ArticStaccatoAbove
        case "noteheadParenthesis":
            return MusicFontSymbol.NoteheadParenthesis
        case "stringsUpBow":
            return MusicFontSymbol.StringsUpBow
        case "stringsDownBow":
            return MusicFontSymbol.StringsDownBow
        case "guitarGolpe":
            return MusicFontSymbol.GuitarGolpe
        default:
            return MusicFontSymbol.None
        }
    }

    internal static func parseTechniqueSymbolPlacement(_ txt: String) -> TechniqueSymbolPlacement {
        switch txt {
        case "outside":
            return TechniqueSymbolPlacement.Outside
        case "inside":
            return TechniqueSymbolPlacement.Inside
        case "above":
            return TechniqueSymbolPlacement.Above
        case "below":
            return TechniqueSymbolPlacement.Below
        default:
            return TechniqueSymbolPlacement.Outside
        }
    }

